</div>

<div id="workspace">
    <div id="poster-board"></div>
</div>

<script>
    document.addEventListener('DOMContentLoaded', () => {
        const board = document.getElementById('poster-board');
        const feedbackPanel = document.getElementById('feedback-panel');

        let draggedEl = null;
        let offsetX = 0;
        let offsetY = 0;
        let stampCounter = 0;

        // Setup Buttons
        document.getElementById('btn-landmark').addEventListener('click', () => createStamp('landmark', 'Monument'));
        document.getElementById('btn-texture').addEventListener('click', () => createStamp('texture', 'Pattern'));
        document.getElementById('btn-type').addEventListener('click', () => createStamp('type', 'VISIT NOW'));
        document.getElementById('btn-sticker').addEventListener('click', () => createStamp('sticker', '★'));
        document.getElementById('btn-reset').addEventListener('click', resetBoard);
        document.getElementById('btn-export').addEventListener('click', exportBrief);

        function createStamp(type, text) {
            const el = document.createElement('div');
            el.className = 'stamp';
            el.dataset.type = type;
            el.dataset.id = `stamp-${stampCounter++}`;
            el.textContent = text;

            // Initial center placement
            el.style.left = '150px';
            el.style.top = '200px';

            board.appendChild(el);
            evaluateComposition();
        }

        // Drag and Drop Logic
        document.addEventListener('mousedown', (e) => {
            if (e.target.classList.contains('stamp')) {
                draggedEl = e.target;
                const rect = draggedEl.getBoundingClientRect();
                offsetX = e.clientX - rect.left;
                offsetY = e.clientY - rect.top;
                // Bring to front
                Array.from(board.children).forEach(child => child.style.zIndex = 1);
                draggedEl.style.zIndex = 10;
            }
        });

        document.addEventListener('mousemove', (e) => {
            if (!draggedEl) return;

            const boardRect = board.getBoundingClientRect();
            let newX = e.clientX - boardRect.left - offsetX;
            let newY = e.clientY - boardRect.top - offsetY;

            draggedEl.style.left = `${newX}px`;
            draggedEl.style.top = `${newY}px`;
        });

        document.addEventListener('mouseup', () => {
            if (draggedEl) {
                draggedEl = null;
                evaluateComposition();
            }
        });

        // Scoring & Feedback Logic
        function evaluateComposition() {
            const stamps = Array.from(board.children);
            if (stamps.length === 0) {
                feedbackPanel.innerHTML = "Score: 0<br>Add elements to begin composing.";
                return;
            }

            let score = 0;
            let feedback = [];
            const typesPresent = new Set(stamps.map(s => s.dataset.type));

            // Goal 1: Diversity
            if (typesPresent.size === 4) {
                score += 40;
                feedback.push("✓ Great element diversity.");
            } else {
                feedback.push("- Try using all four stamp types.");
            }

            // Goal 2: Typography Placement
            const typeStamps = stamps.filter(s => s.dataset.type === 'type');
            if (typeStamps.length > 0) {
                const typeTop = parseInt(typeStamps[0].style.top || 0);
                if (typeTop < 200) {
                    score += 30;
                    feedback.push("✓ Strong headline placement.");
                } else {
                    feedback.push("- Headlines usually work best near the top.");
                }
            }

            // Goal 3: Clutter management
            if (stamps.length > 2 && stamps.length < 8) {
                score += 30;
                feedback.push("✓ Good composition balance.");
            } else if (stamps.length >= 8) {
                score += 10;
                feedback.push("- Getting a bit cluttered.");
            }

            feedbackPanel.innerHTML = `<strong>Score: ${score}/100</strong><br><br>${feedback.join('<br>')}`;
            board.dataset.currentScore = score;
        }

        function resetBoard() {
            board.innerHTML = '';
            stampCounter = 0;
            evaluateComposition();
        }

        function exportBrief() {
            const stamps = Array.from(board.children);
            const score = board.dataset.currentScore || 0;

            const layoutDetails = stamps.map(s => 
                `- ${s.dataset.type} at (x: ${parseInt(s.style.left)}, y: ${parseInt(s.style.top)})`
            ).join('\n');

            const brief = `POSTER COMPOSITION BRIEF\n` +
                          `========================\n` +
                          `Final Score: ${score}/100\n` +
                          `Total Elements: ${stamps.length}\n\n` +
                          `Layout Map:\n${layoutDetails || "Blank Canvas"}`;

            // Create temporary textarea for reliable clipboard copy without newer API permission prompts
            const textArea = document.createElement("textarea");
            textArea.value = brief;
            document.body.appendChild(textArea);
            textArea.select();

            try {
                document.execCommand('copy');
                const btn = document.getElementById('btn-export');
                const originalText = btn.textContent;
                btn.textContent = "Copied!";
                setTimeout(() => btn.textContent = originalText, 2000);
            } catch (err) {
                console.error('Failed to copy brief', err);
            }

            document.body.removeChild(textArea);
        }
    });
</script>
</body>
</html>

