<body>

<div id="sidebar">
    <h2>Poster Tools</h2>
    <button id="btn-landmark">Add Landmark</button>
    <button id="btn-texture">Add Texture</button>
    <button id="btn-type">Add Typography</button>
    <button id="btn-sticker">Add Sticker</button>
    <div class="divider"></div>
    <div id="feedback-panel"></div>
    <button id="btn-reset">Reset Board</button>
    <button id="btn-export" class="primary-btn">Copy Poster Brief</button>
</div>

<div id="workspace">
    <div id="poster-board"></div>
</div>

<script>
    document.addEventListener('DOMContentLoaded', () => {
        const board = document.getElementById('poster-board');
        const feedbackPanel = document.getElementById('feedback-panel');
        const workspace = document.getElementById('workspace');

        let draggedEl = null;
        let offsetX = 0;
        let offsetY = 0;
        let stampCounter = 0;
        let currentScale = 1;

        // Scaling Logic to prevent horizontal clipping
        function resizeBoard() {
            const pad = 30; // Safety padding
            const availableWidth = workspace.clientWidth - pad;

            // Calculate scale to fit width (max scale is 1)
            currentScale = Math.min(1, availableWidth / 500);
            board.style.transform = `scale(${currentScale})`;
        }

        window.addEventListener('resize', resizeBoard);
        resizeBoard(); // Initial scale

        // Setup Buttons
        document.getElementById('btn-landmark').addEventListener('click', () => createStamp('landmark', 'Monument'));
        document.getElementById('btn-texture').addEventListener('click', () => createStamp('texture', 'Pattern'));
        document.getElementById('btn-type').addEventListener('click', () => createStamp('type', 'VISIT NOW'));
        document.getElementById('btn-sticker').addEventListener('click', () => createStamp('sticker', '★'));
        document.getElementById('btn-reset').addEventListener('click', resetBoard);
        document.getElementById('btn-export').addEventListener('click', exportBrief);

        // Initialize empty state
        evaluateComposition();

        function createStamp(type, text) {
            const el = document.createElement('div');
            el.className = 'stamp';
            el.dataset.type = type;
            el.dataset.id = `stamp-${stampCounter++}`;
            el.textContent = text;

            // Initial center placement
            el.style.left = '150px';
            el.style.top = '200px';

            board.appendChild(el);
            evaluateComposition();
        }

        // Drag and Drop Logic (Using Pointer Events for universal Touch/Mouse support)
        document.addEventListener('pointerdown', (e) => {
            if (e.target.classList.contains('stamp')) {
                draggedEl = e.target;
                const rect = draggedEl.getBoundingClientRect();

                // Divide by currentScale to convert viewport pixels to scaled board pixels
                offsetX = (e.clientX - rect.left) / currentScale;
                offsetY = (e.clientY - rect.top) / currentScale;

                // Bring to front
                Array.from(board.children).forEach(child => child.style.zIndex = 1);
                draggedEl.style.zIndex = 10;
            }
        });

        document.addEventListener('pointermove', (e) => {
            if (!draggedEl) return;

            const boardRect = board.getBoundingClientRect();

            // Calculate new position converting to unscaled pixel coordinates
            let newX = (e.clientX - boardRect.left) / currentScale - offsetX;
            let newY = (e.clientY - boardRect.top) / currentScale - offsetY;

            draggedEl.style.left = `${newX}px`;
            draggedEl.style.top = `${newY}px`;
        });

        document.addEventListener('pointerup', () => {
            if (draggedEl) {
                draggedEl = null;
                evaluateComposition();
            }
        });

        function renderFeedback(score, messages) {
            feedbackPanel.replaceChildren();

            const scoreEl = document.createElement('strong');
            scoreEl.textContent = `Score: ${score}/100`;
            feedbackPanel.appendChild(scoreEl);

            feedbackPanel.appendChild(document.createElement('br'));
            feedbackPanel.appendChild(document.createElement('br'));

            messages.forEach(msg => {
                const textNode = document.createTextNode(msg);
                feedbackPanel.appendChild(textNode);
                feedbackPanel.appendChild(document.createElement('br'));
            });
        }

        // Scoring & Feedback Logic
        function evaluateComposition() {
            const stamps = Array.from(board.children);
            if (stamps.length === 0) {
                renderFeedback(0, ["Add elements to begin composing."]);
                return;
            }

            let score = 0;
            let feedback = [];
            const typesPresent = new Set(stamps.map(s => s.dataset.type));

            // Goal 1: Diversity
            if (typesPresent.size === 4) {
                score += 40;
                feedback.push("✓ Great element diversity.");
            } else {
                feedback.push("- Try using all four stamp types.");
            }

            // Goal 2: Typography Placement
            const typeStamps = stamps.filter(s => s.dataset.type === 'type');
            if (typeStamps.length > 0) {
                const typeTop = parseInt(typeStamps[0].style.top || 0);
                if (typeTop < 200) {
                    score += 30;
                    feedback.push("✓ Strong headline placement.");
                } else {
                    feedback.push("- Headlines usually work best near the top.");
                }
            }

            // Goal 3: Clutter management
            if (stamps.length > 2 && stamps.length < 8) {
                score += 30;
                feedback.push("✓ Good composition balance.");
            } else if (stamps.length >= 8) {
                score += 10;
                feedback.push("- Getting a bit cluttered.");
            }

            renderFeedback(score, feedback);
            board.dataset.currentScore = score;
        }

        function resetBoard() {
            board.replaceChildren();
            stampCounter = 0;
            evaluateComposition();
        }

        function exportBrief() {
            const stamps = Array.from(board.children);
            const score = board.dataset.currentScore || 0;

            const layoutDetails = stamps.map(s => 
                `- ${s.dataset.type} at (x: ${parseInt(s.style.left)}, y: ${parseInt(s.style.top)})`
            ).join('\n');

            const brief = `POSTER COMPOSITION BRIEF\n` +
                          `========================\n` +
                          `Final Score: ${score}/100\n` +
                          `Total Elements: ${stamps.length}\n\n` +
                          `Layout Map:\n${layoutDetails || "Blank Canvas"}`;

            const textArea = document.createElement("textarea");
            textArea.value = brief;
            document.body.appendChild(textArea);
            textArea.select();

            try {
                document.execCommand('copy');
                const btn = document.getElementById('btn-export');
                const originalText = btn.textContent;
                btn.textContent = "Copied!";
                setTimeout(() => btn.textContent = originalText, 2000);
            } catch (err) {
                console.error('Failed to copy brief', err);
            }

            document.body.removeChild(textArea);
        }
    });
</script>
</body>
</html>

